const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define San Jose region
  const sanJose = ee.Geometry.Point([-121.8863, 37.3382]);
  const region = sanJose.buffer(25000); // 25km buffer

  // Cloud masking function for Landsat 8
  const maskClouds = (img) => {
    const qa = img.select('pixel_qa');
    const mask = qa.bitwiseAnd(1 << 3).eq(0).and(qa.bitwiseAnd(1 << 5).eq(0));
    return img.updateMask(mask);
  };

  // Calculate NBR (Normalized Burn Ratio)
  const calcNBR = (img) => {
    const nir = img.select('B5');
    const swir = img.select('B7');
    const nbr = nir.subtract(swir).divide(nir.add(swir)).rename('NBR');
    return img.addBands(nbr);
  };

  // June 2020 collection
  const june2020 = ee.ImageCollection('LANDSAT/LC08/C01/T1')
    .filterBounds(region)
    .filterDate('2020-06-01', '2020-06-30')
    .map(maskClouds)
    .map(calcNBR);

  const juneSize = june2020.size().getInfo();
  console.log(`June 2020 Images: ${juneSize}`);

  if (juneSize === 0) {
    console.log('C1');
    return;
  }

  // August 26, 2020 collection
  const august2020 = ee.ImageCollection('LANDSAT/LC08/C01/T1')
    .filterBounds(region)
    .filterDate('2020-08-20', '2020-08-31')
    .map(maskClouds)
    .map(calcNBR);

  const augSize = august2020.size().getInfo();
  console.log(`August 2020 Images: ${augSize}`);

  if (augSize === 0) {
    console.log('C1');
    return;
  }

  // Composite and get median NBR
  const juneComp = june2020.median();
  const augComp = august2020.median();

  // Count valid pixels (NBR exists)
  const juneCount = juneComp.select('NBR').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const augCount = augComp.select('NBR').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const juneValidPixels = juneCount.NBR || 0;
  const augValidPixels = augCount.NBR || 0;

  console.log(`June Valid Pixels: ${juneValidPixels}, August Valid Pixels: ${augValidPixels}`);

  if (juneValidPixels === 0 || augValidPixels === 0) {
    console.log('C2');
    return;
  }

  // Define burned area as NBR < -0.1 (threshold for burned vegetation)
  const juneBurned = juneComp.select('NBR').lt(-0.1);
  const augBurned = augComp.select('NBR').lt(-0.1);

  // Count burned pixels
  const juneBurnedCount = juneBurned.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: region,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const augBurnedCount = augBurned.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: region,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const juneBurnedPixels = juneBurnedCount.NBR || 0;
  const augBurnedPixels = augBurnedCount.NBR || 0;

  console.log(`June Burned Pixels: ${juneBurnedPixels}`);
  console.log(`August Burned Pixels: ${augBurnedPixels}`);

  // Validate results
  if (juneBurnedPixels === null || augBurnedPixels === null) {
    console.log('C3');
    return;
  }

  // Compare burn scars
  if (augBurnedPixels > juneBurnedPixels) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  return new Promise(async (resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, () => {
      ee.initialize(null, null, async () => {
        try {
          await runAnalysis();
          resolve();
        } catch (e) {
          console.log('D');
          reject(e);
        }
      }, (err) => {
        console.log('D');
        reject(err);
      });
    }, (err) => {
      console.log('D');
      reject(err);
    });
  });
}

initEE().catch(() => {});
